 b=p.read_bytes();(D/'outputs/history-matches.txt.gz').write_bytes(gzip.compress(b));lines=[];pat=re.compile(r'(?<![0-9a-f])(?:'+ '|'.join(o)+r')(?![0-9a-f])',re.I)
